cd /tmp/gddp-eval-wt-uqyspyhd && python3 - <<'EOF'
import re

with open('reports/gddp-dogfood/01-env-var-registry.md') as f:
    lines = f.readlines()

# Collect rows: variable (col2), read site (col3)
rows = []
for ln in lines:
    if not ln.startswith('| `GDDP_'):
        continue
    parts = [p.strip() for p in ln.strip().strip('|').split('|')]
    if len(parts) < 3:
        continue
    var = parts[0].strip('`')
    site = parts[1]
    rows.append((var, site))

print("total rows:", len(rows))

def var_from_site(site, var):
    # find file:line tokens
    toks = re.findall(r'([\w./\-]+\.(?:py|sh)):(\d+)', site)
    return toks

missing_file = []
line_missing_name = []
ok = []
for var, site in rows:
    toks = var_from_site(site, var)
    if not toks:
        missing_file.append((var, site))
        continue
    any_hit = False
    for f, l in toks:
        l = int(l)
        if not __import__('os').path.exists(f):
            missing_file.append((var, site, f))
            continue
        try:
            with open(f, encoding='utf-8', errors='replace') as fh:
                content = fh.readlines()
        except Exception as e:
            missing_file.append((var, site, f, str(e)))
            continue
        if 1 <= l <= len(content) and ('GDDP_' + var.split('GDDP_')[1] if False else var) in content[l-1]:
            any_hit = True
    if any_hit:
        ok.append((var, site))
    else:
        line_missing_name.append((var, site))

print("rows where cited file:line contains the var name:", len(ok))
print("\n--- no valid file:line found ---")
for r in missing_file: print(r)
print("\n--- cited file:line does NOT contain var name ---")
for r in line_missing_name: print(r)
EOF
